+        field.setManualValidation(true);
+        field.setValueChangeMode(ValueChangeMode.EAGER);
+        field.addValueChangeListener(event -> {
+            if (!resetting) {
+                sendButton.setEnabled(true);
+            }
+        });
+    }
+
+    private void send() {
+        if (!sendButton.isEnabled()) {
+            return;
+        }
+
+        String name = value(nameField);
+        String email = value(emailField);
+        String phone = value(phoneField);
+        String message = value(messageField);
+
+        boolean valid = true;
+
+        if (name.isBlank()) {
+            markInvalid(nameField, "Name is required");
+            valid = false;
+        } else {
+            markValid(nameField);
+        }
+
+        if (!email.isBlank() && !EMAIL_PATTERN.matcher(email.trim()).matches()) {
+            markInvalid(emailField, "Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isBlank() && phone.isBlank()) {
+            markInvalid(emailField, "Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            markValid(emailField);
+        }
+
+        if (message.isBlank()) {
+            markInvalid(messageField, "Message is required");
+            valid = false;
+        } else if (message.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(messageField, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        } else {
+            markValid(messageField);
+        }
+
+        if (!valid) {
+            // Nothing is sent and everything the user typed stays in the form.
+            return;
+        }
+
+        MessageStore.current().add(new ContactMessage(name.trim(), email.trim(), phone.trim(), message.trim()));
