+        Notification.show("Message sent", 5000, Notification.Position.TOP_END);
+
+        resetting = true;
+        try {
+            nameField.clear();
+            emailField.clear();
+            phoneField.clear();
+            messageField.clear();
+        } finally {
+            resetting = false;
+        }
