+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Unsent message");
+        dialog.add(new Paragraph("Your message has not been sent yet."));
+        Button keepEditing = new Button("Keep editing", e -> {
+            dialog.close();
+            // Let go of the postponed navigation, so that the next attempt to
+            // leave is a fresh one and asks again.
+            action.cancel();
+        });
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
