+        PlaywrightAssertions.assertThat(page.locator("vaadin-notification-card"))
+                .hasCount(0);
+    }
+
+    @Test
+    void malformedEmail_isReported_andNothingIsSent() {
+        name().setValue("Ada");
+        email().setValue("nope");
+        message().setValue("Hello");
