+
+        grid().assertRowCount(1);
+        grid().assertCellContent(0, "Name", "Ada");
+        grid().assertCellContent(0, "Message", "Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("Grace");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterKey_sends() {
+        name().setValue("Ada");
+        phone().setValue("555");
+        message().setValue("Sent with Enter");
