+
+        grid().assertRowCount(1);
+        assertTrue(new NotificationElement(page).getText().contains("Message sent"));
+    }
+
+    @Test
+    void enterKeyInTheMessageArea_sends() {
+        name().setValue("Ada");
+        phone().setValue("555");
+        message().setValue("Sent from the text area");
