+        grid().assertCellContent(0, "Name", "Ada");
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        page.getByText("About").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        PlaywrightAssertions.assertThat(page.getByText("Keep editing")).hasCount(0);
+        assertEquals(getUrl() + "about", page.url());
+    }
+
+    @Test
+    void dirtyForm_asksBeforeLeaving_andKeepEditingStays() {
+        name().setValue("Ada");
+        message().setValue("Half written");
+
+        page.getByText("About").click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        PlaywrightAssertions.assertThat(page.getByText("Keep editing")).hasCount(0);
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("Ada");
+        message().assertValue("Half written");
+        assertEquals(getUrl() + "contact", page.url());
+    }
+
+    @Test
+    void afterKeepEditing_theNextAttemptAsksAgain() {
+        name().setValue("Ada");
+
+        page.getByText("About").click();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        page.getByText("About").click();
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1"))
+                .hasText("About", new LocatorAssertions.HasTextOptions().setTimeout(5000));
+    }
+
+    @Test
+    void dirtyForm_discardLetsTheNavigationThrough() {
+        phone().setValue("555");
+
+        page.getByText("About").click();
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1"))
+                .hasText("About", new LocatorAssertions.HasTextOptions().setTimeout(5000));
+        assertEquals(getUrl() + "about", page.url());
+    }
+}
