+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessage_isReported() {
+        test(name).setValue("Ada");
+        test(phone).setValue("123");
+        test(message).setValue("x".repeat(501));
+
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void messageOf500Characters_isAccepted() {
+        test(name).setValue("Ada");
+        test(phone).setValue("123");
+        test(message).setValue("x".repeat(500));
+
+        test(send).click();
+
+        assertFalse(message.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validSend_notifies_clearsForm_andDisablesSendUntilNextEdit() {
